BEGIN;
create temp table checks(label text);
create function pg_temp.check(passed boolean,label text) returns void language plpgsql as $$begin
 if passed is not true then raise exception 'FAIL: %',label;end if;insert into checks values(label);end$$;
DO $$
declare p uuid:=gen_random_uuid();l uuid:=gen_random_uuid();other_l uuid:=gen_random_uuid();actor uuid;req uuid:=gen_random_uuid();t uuid;b uuid;legacy uuid:=gen_random_uuid();r jsonb;s jsonb;delivery jsonb;booking jsonb;at timestamptz;
begin
 select id into actor from public.profiles where org_id='22222222-2222-2222-2222-222222222222' order by id limit 1;
 insert into public.properties(id,name,org_id,settings)values(p,'Timezone contract','22222222-2222-2222-2222-222222222222','{"timezone":"UTC"}');
 insert into public.leads(id,property_id,first_name,email,status)values(l,p,'Timezone fixture','fixture@example.invalid','contacted'),(other_l,p,'Other fixture','other@example.invalid','contacted');
 r:=public.book_recorded_console_tour(p,l,actor,req,jsonb_build_object('date',current_date+3,'time','10:00','type','in_person','notes','','sendConfirmation',false));
 t:=(r->>'tourId')::uuid;
 perform pg_temp.check(r->>'state'='applied' and r->'tour'->>'schedule_timezone'='UTC','console booking pins its validated zone');
 perform pg_temp.check((select after_state->>'timezone'='UTC' and after_state->>'startsAt' is not null from public.shared_action_events where id=req),'confirmed console action carries the booked zone and instant');
 at:=(public.tour_outcome_schedule(p,'tours',t)->>'startsAt')::timestamptz;
 update public.properties set settings='{"timezone":"America/Los_Angeles"}' where id=p;
 perform pg_temp.check((public.tour_outcome_schedule(p,'tours',t)->>'startsAt')::timestamptz=at,'later property settings do not move the appointment');
 perform pg_temp.check(public.tour_reminder_schedule(p,'tours',t)->>'timezone'='UTC','reminders use the pinned appointment zone');
 r:=public.change_tour_schedule(p,l,'tours',t,actor,gen_random_uuid(),1,jsonb_build_object('action','reschedule','date',current_date+4,'time','11:00','reason','Fixture change','notify',false));
 perform pg_temp.check(r->>'state'='applied' and r->'tour'->>'schedule_timezone'='UTC','rescheduling preserves the existing booked clock');
 perform pg_temp.check(public.tour_outcome_schedule(p,'tours',t)->>'timezone'='UTC','changed schedule still resolves in its original zone');
 begin update public.tours set schedule_timezone='America/New_York' where id=t;raise exception 'FAIL: timezone rewritten';
 exception when sqlstate '55000' then insert into checks values('direct booked timezone rewrite rejected');end;
 update public.properties set settings='{"timezone":"America/New_York"}' where id=p;
 booking:=jsonb_build_object('scheduled_date',current_date+5,'scheduled_time','09:00','duration_minutes',45,'source','lumaleasing');
 at:=((current_date+5)+'09:00'::time) at time zone 'America/New_York';
 delivery:=jsonb_build_object('timezone','America/New_York','startsAt',at,'leadInfo',jsonb_build_object('email','fixture@example.invalid'));
 r:=public.reserve_luma_tour(p,l,booking,delivery);b:=(r->'booking'->>'id')::uuid;
 perform pg_temp.check(r->'booking'->>'schedule_timezone'='America/New_York','public booking pins its validated zone');
 perform pg_temp.check((select payload->>'timezone'='America/New_York' and (payload->>'startsAt')::timestamptz=at and payload->>'durationMinutes'='45' from public.luma_delivery_jobs where booking_id=b),'delivery stores the authoritative booking instant and duration');
 update public.properties set settings='{"timezone":"Asia/Kolkata"}' where id=p;
 perform pg_temp.check((public.tour_outcome_schedule(p,'tour_bookings',b)->>'startsAt')::timestamptz=at,'public booking retains its original instant after configuration changes');
 r:=public.reserve_luma_tour(p,l,booking,delivery);
 perform pg_temp.check(r->>'duplicate'='true' and r->'booking'->>'schedule_timezone'='America/New_York','replay returns the original booked clock');
 perform pg_temp.check((select count(*)=1 from public.luma_delivery_jobs where booking_id=b),'timezone changes and replay do not duplicate delivery');
 begin perform public.reserve_luma_tour(p,other_l,booking||jsonb_build_object('scheduled_date',current_date+6),delivery);raise exception 'FAIL: stale timezone accepted';
 exception when sqlstate '40001' then insert into checks values('concurrent configuration change rejects a stale booking context');end;
 perform pg_temp.check(not exists(select 1 from public.tour_bookings where lead_id=other_l),'rejected context leaves no reservation');
 update public.properties set settings='{"timezone":"America/New_York"}' where id=p;
 begin perform public.reserve_luma_tour(p,other_l,booking||'{"scheduled_date":"2099-03-08","scheduled_time":"02:30"}','{}');raise exception 'FAIL: gap accepted';
 exception when sqlstate '22023' then insert into checks values('public booking rejects a nonexistent DST clock');end;
 begin perform public.reserve_luma_tour(p,other_l,booking||'{"scheduled_date":"2099-11-01","scheduled_time":"01:30"}','{}');raise exception 'FAIL: fold accepted';
 exception when sqlstate '22023' then insert into checks values('public booking rejects an ambiguous DST clock');end;
 begin perform public.reserve_luma_tour(p,other_l,booking||jsonb_build_object('scheduled_date',current_date-1),'{}');raise exception 'FAIL: past accepted';
 exception when sqlstate '22023' then insert into checks values('public booking rejects a past instant');end;
 update public.properties set settings='{"timezone":"America/Los_Angeles"}' where id=p;
 at:=(public.tour_outcome_schedule(p,'tours',t)->>'startsAt')::timestamptz;
 begin perform public.reserve_luma_tour(p,other_l,jsonb_build_object('scheduled_date',(at at time zone 'America/Los_Angeles')::date,'scheduled_time',(at at time zone 'America/Los_Angeles')::time,'duration_minutes',30,'source','lumaleasing'),'{}');raise exception 'FAIL: cross-zone overlap accepted';
 exception when raise_exception then if sqlerrm like 'FAIL:%' then raise;end if;insert into checks values('shared capacity rejects equal instants expressed in different booked zones');end;
 r:=public.reserve_luma_tour(p,other_l,jsonb_build_object('scheduled_date',current_date+4,'scheduled_time','11:00','duration_minutes',30,'source','lumaleasing'),'{}');
 perform pg_temp.check(r->'booking'->>'id' is not null,'shared capacity allows equal clock labels at different actual instants');
 update public.properties set settings='{}' where id=p;
 begin perform public.reserve_luma_tour(p,other_l,booking,'{}');raise exception 'FAIL: unknown zone accepted';
 exception when sqlstate '22023' then insert into checks values('public booking rejects an unknown property timezone');end;
 insert into public.tours(id,property_id,lead_id,tour_date,tour_time,status)values(legacy,p,l,current_date-1,'10:00','completed');
 perform pg_temp.check((select schedule_timezone is null from public.tours where id=legacy),'historical rows are not backfilled from current settings');
 perform pg_temp.check(not has_function_privilege('authenticated','public.protect_tour_timezone()','execute'),'timezone guard is not a client RPC');
end$$;
select count(*) as passed from checks;
ROLLBACK;
